import{_ as l,a0 as p,w as o,s as d,ao as r,I as i,x as e,a1 as n,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const L=JSON.parse('{"title":"我喜欢在 Linux 命令行中使用的 6 个元字符 | LCTT x X-CMD","titleTemplate":false,"description":"我喜欢在 Linux 命令行中使用的 6 个元字符 | LCTT (202202) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我喜欢在 Linux 命令行中使用的 6 个元字符 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我喜欢在 Linux 命令行中使用的 6 个元字符 | LCTT (202202) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202202/20220209 6 Linux metacharacters I love to use on the command line","title":"我喜欢在 Linux 命令行中使用的 6 个元字符","tag":"202202","desc":""},"relativePath":"202202/20220209 6 Linux metacharacters I love to use on the command line.md","filePath":"[post].md"}'),c={name:"202202/20220209 6 Linux metacharacters I love to use on the command line.md"};function h(u,s,g,k,m,b){const a=p("Link");return o(),d("div",null,[s[18]||(s[18]=r(`<h1 id="我喜欢在-linux-命令行中使用的-6-个元字符" tabindex="-1">我喜欢在 Linux 命令行中使用的 6 个元字符 <a class="header-anchor" href="#我喜欢在-linux-命令行中使用的-6-个元字符" aria-label="Permalink to “我喜欢在 Linux 命令行中使用的 6 个元字符”">​</a></h1><blockquote><p>在 Linux 命令行上使用元字符是提高生产力的一个好方法。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202202/13/235915kbphrm6ld6yi2hud.jpg" alt=""></p><p>在我的 Linux 之旅的早期，我学会了如何使用命令行。这就是 Linux 的与众不同之处。我可以失去图形用户界面（GUI），但没有必要完全重建机器。许多 Linux 电脑是<ruby>无头<rt>headless</rt></ruby>运行的，你可以在命令行上完成所有的管理任务。它使用许多所有人都熟悉的基本命令，如 <code>ls</code>、<code>ls-l</code>、<code>ls-l</code>、<code>cd</code>、<code>pwd</code>、<code>top</code> 等等。</p><h3 id="linux-上的-shell-元字符" tabindex="-1">Linux 上的 Shell 元字符 <a class="header-anchor" href="#linux-上的-shell-元字符" aria-label="Permalink to “Linux 上的 Shell 元字符”">​</a></h3><p>你可以通过使用元字符来扩展这些命令。我不知道你怎么称呼它们，但这些元字符使我的生活变得更轻松。</p><h3 id="管道符" tabindex="-1">管道符 | <a class="header-anchor" href="#管道符" aria-label="Permalink to “管道符 |”">​</a></h3><p>假设我想知道我的系统上运行的 Firefox 的所有实例。我可以使用带有 <code>-ef</code> 参数的 <code>ps</code> 命令来列出我系统上运行的所有程序实例。现在我想只看那些涉及 Firefox 的实例。我使用了我最喜欢的元字符之一，管道符 <code>|</code>，将其结果送到 <code>grep</code>，用它来搜索模式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ps -ef | grep firefox</span></span></code></pre></div><h3 id="输出重定向" tabindex="-1">输出重定向 &gt; <a class="header-anchor" href="#输出重定向" aria-label="Permalink to “输出重定向 &gt;”">​</a></h3><p>另一个我最喜欢的元字符是输出重定向 <code>&gt;</code>。我用它来打印 <code>dmesg</code> 命令结果中所有 AMD 相关的结果。你可能会发现这在硬件故障排除中很有帮助：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dmesg | grep amd &gt; amd.txt</span></span>
<span class="line"><span>$ cat amd.txt</span></span>
<span class="line"><span>[ 0.897] amd_uncore: 4 amd_df counters detected</span></span>
<span class="line"><span>[ 0.897] amd_uncore: 6 amd_l3 counters detected</span></span>
<span class="line"><span>[ 0.898] perf/amd_iommu: Detected AMD IOMMU #0 (2 banks, 4 counters/bank).</span></span></code></pre></div><h3 id="星号" tabindex="-1">星号 * <a class="header-anchor" href="#星号" aria-label="Permalink to “星号 *”">​</a></h3><p>星号 <code>*</code>（通配符）是寻找具有相同扩展名的文件时我的最爱，如 <code>.jpg</code> 或 <code>.png</code>。我首先进入我的系统中的 <code>Picture</code> 目录，并使用类似以下的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.png</span></span>
<span class="line"><span>BlountScreenPicture.png</span></span>
<span class="line"><span>DisplaySettings.png</span></span>
<span class="line"><span>EbookStats.png</span></span>
<span class="line"><span>StrategicPlanMenu.png</span></span>
<span class="line"><span>Screenshot from 01-24 19-35-05.png</span></span></code></pre></div><h3 id="波浪号" tabindex="-1">波浪号 ~ <a class="header-anchor" href="#波浪号" aria-label="Permalink to “波浪号 ~”">​</a></h3><p>波浪号 <code>~</code> 是在 Linux 系统上通过输入以下命令快速返回你的家目录的一种方法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd ~</span></span>
<span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/don</span></span></code></pre></div><h3 id="美元符号" tabindex="-1">美元符号 $ <a class="header-anchor" href="#美元符号" aria-label="Permalink to “美元符号 $”">​</a></h3><p><code>$</code> 符号作为一个元字符有不同的含义。当用于匹配模式时，它意味着任何以给定字符串结尾的字符串。例如，当同时使用元字符 <code>|</code> 和 <code>$</code> 时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | grep png$</span></span>
<span class="line"><span>BlountScreenPicture.png</span></span>
<span class="line"><span>DisplaySettings.png</span></span>
<span class="line"><span>EbookStats.png</span></span>
<span class="line"><span>StrategicPlanMenu.png</span></span>
<span class="line"><span>Screenshot from 01-24 19-35-05.png</span></span></code></pre></div><h3 id="上尖号" tabindex="-1">上尖号 ^ <a class="header-anchor" href="#上尖号" aria-label="Permalink to “上尖号 ^”">​</a></h3><p>符号 <code>^</code> 将结果限制在以给定字符串开始的项目上。例如，当同时使用元字符 <code>|</code> 和 <code>^</code> 时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls | grep ^Screen</span></span>
<span class="line"><span>Screenshot from 01-24 19-35-05.png</span></span></code></pre></div>`,24)),i("p",null,[s[1]||(s[1]=e("这些元字符中有许多是通往 ",-1)),n(a,{href:"https://opensource.com/article/18/5/getting-started-regular-expressions"},{default:t(()=>[...s[0]||(s[0]=[e("正则表达式",-1)])]),_:1}),s[2]||(s[2]=e(" 的大门，所以还有很多东西可以探索。你最喜欢的 Linux 元字符是什么，它们是如何节省你的工作的？",-1))]),s[19]||(s[19]=i("hr",null,null,-1)),i("p",null,[s[4]||(s[4]=e("via: ",-1)),n(a,{href:"https://opensource.com/article/22/2/metacharacters-linux"},{default:t(()=>[...s[3]||(s[3]=[e("https://opensource.com/article/22/2/metacharacters-linux",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=e("作者：",-1)),n(a,{href:"https://opensource.com/users/don-watkins"},{default:t(()=>[...s[5]||(s[5]=[e("Don Watkins",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),n(a,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const C=l(c,[["render",h]]);export{L as __pageData,C as default};
